let a = [[3, -2, 5, 1], [-4, 7, 0, 6], [2, 9, -8, -3]]
let b = [[1, 4], [-5, 2], [6, -1], [0, 7]]
for i in 0..<3 {
    var row = [Int]()
    for j in 0..<2 {
        let sum = (0..<4).reduce(0) { $0 + a[i][$1] * b[$1][j] }
        row.append(sum)
    }
    print(row.map { String(format: "%5d", locale: Locale(identifier: "en_US_POSIX"), $0) }.joined())
